   ["3", "Les Sept Maitres Esprits", "Créateurs Suprêmes", "116:2.7"],
   ["4", "L’Être Suprême", "Personnalisation spirituelle-expérientielle et foyer du pouvoir tout-puissant", "116:2.8, 116:2.12"],
   ["5", "L’Acteur Conjoint", "Déité du Paradis", "116:2.9"],
